const isLive = (cell: Cell, liveCells: Cell[]): boolean =>
  liveCells.some(([x, y]) => x === cell[0] && y === cell[1]);

const neighborsOf = ([x, y]: Cell): Cell[] => [
  [x - 1, y - 1],
  [x, y - 1],
  [x + 1, y - 1],
  [x - 1, y],
  [x + 1, y],
  [x - 1, y + 1],
  [x, y + 1],
  [x + 1, y + 1],
];

const candidates = (liveCells: Cell[]): Cell[] => {
  const all = [...liveCells, ...liveCells.flatMap(neighborsOf)];
  return all.filter(
    (cell, index) => all.findIndex(([x, y]) => x === cell[0] && y === cell[1]) === index,
  );
};

export const nextGeneration = (liveCells: Cell[]): Cell[] =>
  candidates(liveCells).filter((cell) =>
    isLive(cell, liveCells)
      ? survives(cell, liveCells)
      : countLiveNeighbors(cell, liveCells) === 3,
  );
